CREATE OR REPLACE FUNCTION public.search_pseudonyms(_query text) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('pseudonym',s.pseudonym)),'[]'::jsonb) FROM (SELECT pseudonym FROM (SELECT pseudonym FROM public.posts WHERE NOT(is_deleted OR author_deleted OR admin_removed) AND (expires_at IS NULL OR expires_at>now()) UNION SELECT c.pseudonym FROM public.comments c JOIN public.posts p ON p.id=c.post_id WHERE NOT(c.is_deleted OR c.admin_removed OR p.is_deleted OR p.author_deleted OR p.admin_removed) AND (p.expires_at IS NULL OR p.expires_at>now())) visible WHERE char_length(trim(coalesce(_query,''))) BETWEEN 2 AND 80 AND strpos(lower(pseudonym),lower(trim(_query)))>0 ORDER BY pseudonym LIMIT 30) s $$;
CREATE OR REPLACE FUNCTION public.public_pseudonym_profile(_pseudonym text) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT jsonb_build_object('pseudonym',_pseudonym,'posts',(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) FROM (SELECT id,title,body,community,pseudonym,post_type,progress,created_at,expires_at FROM public.posts WHERE pseudonym=_pseudonym AND NOT(is_deleted OR author_deleted OR admin_removed) AND (expires_at IS NULL OR expires_at>now()) ORDER BY created_at DESC LIMIT 50) s),'comments',(SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]'::jsonb) FROM (SELECT c.id,c.post_id,c.body,c.created_at FROM public.comments c JOIN public.posts p ON p.id=c.post_id WHERE c.pseudonym=_pseudonym AND NOT(c.is_deleted OR c.admin_removed OR p.is_deleted OR p.author_deleted OR p.admin_removed) AND (p.expires_at IS NULL OR p.expires_at>now()) ORDER BY c.created_at DESC LIMIT 50) c)) WHERE char_length(_pseudonym) BETWEEN 1 AND 80 $$;